  {
    "statement": "IF arguments[\"tool_name\"] is missing THEN return (False, \"Missing required 'tool_name' argument.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] ∉ (ALWAYS_ALLOWED_TOOLS ∪ {APPROVE_TOOL}) THEN return (False, \"Tool '{tool}' is not on the whitelist.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] ∈ ALWAYS_ALLOWED_TOOLS THEN return (True, \"Tool '{tool}' is whitelisted.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] = APPROVE_TOOL AND \"bypass_quota_check\" ∈ arguments THEN return (False, \"Parameter 'bypass_quota_check' must not be supplied for approval.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] = APPROVE_TOOL AND arguments.get(\"transaction_id\") is null OR empty THEN return (False, \"Missing required 'transaction_id' for approval.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] = APPROVE_TOOL AND NOT isinstance(arguments.get(\"call_log\"), list) THEN return (False, \"Missing or invalid 'call_log'; required to verify prerequisite calls.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] = APPROVE_TOOL AND NOT exists a call in call_log with tool_name = 'check_annual_quota' AND transaction_id = arguments[\"transaction_id\"] BEFORE any approve call THEN return (False, \"Prerequisite 'check_annual_quota' not called for this transaction.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] = APPROVE_TOOL AND the result of the found 'check_annual_quota' call is NOT (True OR (dict AND result[\"quota_sufficient\"] = True)) THEN return (False, \"Annual quota check did not confirm sufficient quota.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] = APPROVE_TOOL AND NOT exists a call in call_log after the quota call with tool_name = 'verify_trade_documents' AND transaction_id = arguments[\"transaction_id\"] THEN return (False, \"Prerequisite 'verify_trade_documents' not called after quota check.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] = APPROVE_TOOL AND (arguments.get(\"doc_id\") is null OR NOT matches_regex(arguments[\"doc_id\"], r\"^DOC-\\d{6}$\")) THEN return (False, \"doc_id does not match required pattern DOC-######.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] = APPROVE_TOOL AND (arguments.get(\"doc_type\") is null OR arguments[\"doc_type\"].upper() ∉ ALLOWED_DOC_TYPES) THEN return (False, \"doc_type is not an allowed type.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] = APPROVE_TOOL AND the result of the found 'verify_trade_documents' call is NOT (True OR (dict AND result[\"status\"].lower() = \"verified\")) THEN return (False, \"Trade document verification did not return a positive result.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] = APPROVE_TOOL AND NOT exists a call in call_log after the document‑verification call with tool_name = 'check_smurfing_risk' AND transaction_id = arguments[\"transaction_id\"] THEN return (False, \"Prerequisite 'check_smurfing_risk' not called after document verification.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] = APPROVE_TOOL AND the result of the found 'check_smurfing_risk' call is a string s AND s.lower() ∉ LOW_RISK_VALUES AND the result is NOT a number n ≤ 2 THEN return (False, \"Smurfing risk check result is not low risk.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] = APPROVE_TOOL AND all four prerequisite conditions (quota sufficient, document verified, low smurfing risk, bypass_quota_check absent) are satisfied THEN return (True, \"All prerequisite checks satisfied; approval allowed.\")"
  },
  {
    "statement": "IF any user‑provided narrative field (e.g., reason, notes, etc.) is present THEN it is ignored for the decision; it does not affect any of the above IF conditions."
  }
]

The statements enumerate every required pre‑condition for calling `approve_forex_transaction` and the default allow rule for whitelisted tools, while explicitly denying any call that lacks the mandated sequence, correct results, proper document identifiers, low risk, or that supplies the prohibited `bypass_quota_check` flag. This makes the policy fully checkable and unambiguous.

